/**
 * Upload API types extracted from Content API OpenAPI spec.
 * These are kept separate to avoid breaking changes when the main spec is regenerated.
 */
type UploadErrorResponse = {
    content: {
        'application/json': {
            code?: string;
            message: string;
        };
    };
};
type UploadErrorResponses = {
    400: UploadErrorResponse;
    401: UploadErrorResponse;
    403: UploadErrorResponse;
    404: UploadErrorResponse;
    503: UploadErrorResponse;
};
export type UploadPaths = {
    '/api/v0/uploads/{collectionId}/{filename}': {
        delete: {
            parameters: {
                path: {
                    collectionId: string;
                    filename: string;
                };
            };
            responses: {
                200: {
                    content: {
                        'application/json': {
                            success: true;
                        };
                    };
                };
            } & UploadErrorResponses;
        };
    };
    '/api/v0/uploads/download/sign': {
        post: {
            requestBody: {
                content: {
                    'application/json': {
                        collectionId: string;
                        expiresIn: number;
                        filename: string;
                        responseHeaders: {
                            cacheControl: string;
                        };
                    };
                };
            };
            responses: {
                200: {
                    content: {
                        'application/json': {
                            url: string;
                        };
                    };
                };
            } & UploadErrorResponses;
        };
    };
    '/api/v0/uploads/multipart/abort': {
        post: {
            requestBody: {
                content: {
                    'application/json': {
                        collectionId: string;
                        filename: string;
                        uploadId: string;
                    };
                };
            };
            responses: {
                200: {
                    content: {
                        'application/json': {
                            success: true;
                        };
                    };
                };
            } & UploadErrorResponses;
        };
    };
    '/api/v0/uploads/multipart/complete': {
        post: {
            requestBody: {
                content: {
                    'application/json': {
                        collectionId: string;
                        filename: string;
                        parts: Array<{
                            ETag: string;
                            PartNumber: number;
                        }>;
                        uploadId: string;
                    };
                };
            };
            responses: {
                200: {
                    content: {
                        'application/json': {
                            success: true;
                        };
                    };
                };
            } & UploadErrorResponses;
        };
    };
    '/api/v0/uploads/multipart/initiate': {
        post: {
            requestBody: {
                content: {
                    'application/json': {
                        collectionId: string;
                        contentType: string;
                        filename: string;
                    };
                };
            };
            responses: {
                200: {
                    content: {
                        'application/json': {
                            uploadId: string;
                        };
                    };
                };
            } & UploadErrorResponses;
        };
    };
    '/api/v0/uploads/multipart/parts': {
        post: {
            requestBody: {
                content: {
                    'application/json': {
                        collectionId: string;
                        expiresIn: number;
                        filename: string;
                        partNumbers: number[];
                        uploadId: string;
                    };
                };
            };
            responses: {
                200: {
                    content: {
                        'application/json': {
                            parts: Array<{
                                partNumber: number;
                                url: string;
                            }>;
                        };
                    };
                };
            } & UploadErrorResponses;
        };
    };
    '/api/v0/uploads/sign': {
        post: {
            requestBody: {
                content: {
                    'application/json': {
                        collectionId: string;
                        contentType?: string;
                        expiresIn: number;
                        filename: string;
                    };
                };
            };
            responses: {
                200: {
                    content: {
                        'application/json': {
                            url: string;
                        };
                    };
                };
            } & UploadErrorResponses;
        };
    };
};
export {};
